const v20Root=fs.mkdtempSync(path.join(os.tmpdir(),'viral-v20-'));const [opsHealth,journal20]=await Promise.all([import('./operational-health.mjs'),import('./execution-journal.mjs')]);journal20.recordExecution(v20Root,{backlogId:'b-done',type:'repurpose-winner',status:'completed',ownerConfirmed:true});assert.ok(journal20.completedExecutionForBacklog(v20Root,'b-done'));const health20=opsHealth.operationalHealth({projects:[{id:'p-stale',status:'rendering',updatedAt:'2026-01-01T00:00:00Z'}],runs:[{id:'r-stale',status:'producing',updatedAt:'2026-01-01T00:00:00Z'}],backlog:[{id:'b-stale',status:'in-progress',updatedAt:'2026-01-01T00:00:00Z'}],executions:[{id:'old-fail',status:'failed',createdAt:'2026-09-14T00:00:00Z'},{id:'recent-fail',status:'failed',createdAt:'2026-09-14T23:30:00Z'}],capacity:{capacity:1},now:Date.parse('2026-09-15T00:00:00Z'),staleMinutes:45,failureWindowMinutes:60});assert.equal(health20.status,'critical');assert.equal(health20.incidents.length,3);assert.equal(health20.recentExecutionFailures,1);assert.equal(health20.recentFailures[0].id,'recent-fail');assert.ok(health20.reasons.some(x=>x.includes('execution failure')));const preview20=opsHealth.maintenancePreview(health20,{limit:10});assert.equal(preview20.count,1);assert.equal(preview20.resetBacklog[0].id,'b-stale');assert.equal(preview20.blocked.projects,1);assert.equal(preview20.blocked.runs,1);assert.equal(preview20.policy.previewOnly,true);assert.equal(preview20.policy.stateBoundConfirmation,true);assert.equal(preview20.previewToken.length,64);assert.equal(opsHealth.maintenancePreviewMatches(preview20,preview20.previewToken),true);const changedPreview20=opsHealth.maintenancePreview({...health20,incidents:health20.incidents.filter(x=>x.id!=='b-stale')},{limit:10});assert.equal(opsHealth.maintenancePreviewMatches(changedPreview20,preview20.previewToken),false);assert.equal(opsHealth.maintenancePreviewMatches(preview20,'bad-token'),false);assert.equal(health20.policy.autoRecover,false);assert.equal(health20.policy.autoPublish,false);fs.rmSync(v20Root,{recursive:true,force:true});

const v23mods=await Promise.all([import('./execution-preview.mjs'),import('./execution-reconciliation.mjs')]);
